package com.shanjay.mart.dao;
import com.shanjay.mart.model.CartItem; import java.sql.*; import javax.sql.DataSource; import java.util.*; import java.math.*;
public class CartDAO {private final DataSource ds; public CartDAO(DataSource ds){this.ds=ds;} public List<CartItem> list(long b)throws SQLException{List<CartItem>a=new ArrayList<>();String q="SELECT c.id,c.product_id,p.seller_id,p.name,p.price,c.quantity FROM cart_items c JOIN products p ON p.id=c.product_id WHERE c.buyer_id=?";try(Connection x=ds.getConnection();PreparedStatement p=x.prepareStatement(q)){p.setLong(1,b);try(ResultSet r=p.executeQuery()){while(r.next()){CartItem i=new CartItem();i.id=r.getLong(1);i.productId=r.getLong(2);i.sellerId=r.getLong(3);i.name=r.getString(4);i.price=r.getBigDecimal(5);i.quantity=r.getInt(6);a.add(i);}}}return a;} public void add(long b,long pid,int qty)throws SQLException{String q="MERGE INTO cart_items(buyer_id,product_id,quantity) KEY(buyer_id,product_id) VALUES(?,?,COALESCE((SELECT quantity FROM cart_items WHERE buyer_id=? AND product_id=?),0)+?)";try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement(q)){p.setLong(1,b);p.setLong(2,pid);p.setLong(3,b);p.setLong(4,pid);p.setInt(5,qty);p.executeUpdate();}} public void remove(long b,long pid)throws SQLException{try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM cart_items WHERE buyer_id=? AND product_id=?")){p.setLong(1,b);p.setLong(2,pid);p.executeUpdate();}} public void clear(long b)throws SQLException{try(Connection c=ds.getConnection();PreparedStatement p=c.prepareStatement("DELETE FROM cart_items WHERE buyer_id=?")){p.setLong(1,b);p.executeUpdate();}}}
